INSERT INTO listening_lesson (id, lesson_no, title, audio_key, duration_ms, sort_order) VALUES ('listen-16', 16, '第16課 听力训练', 'listening/listening-lesson-16.mp3', 168229, 0);
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn16-s1', 'listen-16', 1, 'text', '听录音，根据录音中的内容仿照例子写下相应的数字。', 17032, 84973, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn16-s1-q1', 'lsn16-s1', 1, '全部でいくらぐらいかかりましたか。＿＿円です。', '[]'::jsonb, '420');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn16-s1-q2', 'lsn16-s1', 2, '一日で何時間ぐらい勉強しますか。＿＿時間です。', '[]'::jsonb, '6');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn16-s1-q3', 'lsn16-s1', 3, '今年は何ヶ月ぐらい上海にいましたか。＿＿ヶ月です。', '[]'::jsonb, '2');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l1', 'lsn16-s1', 1, 'A', 17332, 20768, 'スーパーで何を買いましたか。', 'A：在超市买了什么？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l2', 'lsn16-s1', 2, 'B', 21563, 27310, '150円のりんごを２つ買いました。それから120円のアイスクリームを１つ。', 'B：买了两个150日元的苹果，还有一个120日元的冰淇淋。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l3', 'lsn16-s1', 3, 'A', 28239, 30545, 'え？アイスを１つだけ？', 'A：诶？冰淇淋只买一个？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l4', 'lsn16-s1', 4, 'B', 31550, 35201, 'そうですよ。あなたは食べませんよね。', 'B：是啊。你不吃吧。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l5', 'lsn16-s1', 5, 'A', 40157, 47334, '勉強は忙しいですか。', 'A：学习忙吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l6', 'lsn16-s1', 6, 'B', 49832, 56939, 'はい、朝3時間ぐらい勉強します。それから、夜7時から10時まで図書館で勉強します。', 'B：忙。早上学3个小时左右，然后晚上7点到10点在图书馆学习。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l7', 'lsn16-s1', 7, 'A', 57886, 60511, 'すごいですね。', 'A：真厉害。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l8', 'lsn16-s1', 8, 'A', 65457, 73339, 'よく上海に行きますか。', 'A：经常去上海吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l9', 'lsn16-s1', 9, 'B', 74469, 77251, '上海に会社がありますので、よく行きます。', 'B：公司在上海，所以经常去。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s1-l10', 'lsn16-s1', 10, 'A', 78688, 84273, 'じゃ、２月と３月は、ずっと上海でしたよね。', 'A：那2月和3月一直在上海吧。');
INSERT INTO listening_section (id, lesson_id, section_no, kind, instruction, audio_start_ms, audio_end_ms, example_prompt, example_answer) VALUES ('lsn16-s2', 'listen-16', 2, 'choice', '听录音，根据录音中的内容，将正确答案写在括号中。背景：男生和女生在对话。', 105350, 159007, '', '');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn16-s2-q1', 'lsn16-s2', 1, '女の人は、この後、何をしますか。', '[{"key":"a","text":"病院に行きます。"},{"key":"b","text":"休みます。"},{"key":"c","text":"薬を飲みます。"}]'::jsonb, 'c');
INSERT INTO listening_question (id, section_id, question_no, prompt, options, answer) VALUES ('lsn16-s2-q2', 'lsn16-s2', 2, '女の人は、今週の日曜日、何をしますか。', '[{"key":"a","text":"何もしません。"},{"key":"b","text":"会社で残業します。"},{"key":"c","text":"博物館へ行きます。"}]'::jsonb, 'b');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l1', 'lsn16-s2', 1, '男', 105650, 110536, '伊藤さん、大丈夫ですか。顔色が悪いですね。', '男：伊藤，你没事吧？脸色不太好。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l2', 'lsn16-s2', 2, '女', 111154, 114449, 'ええ、ちょっと頭が痛いんです。', '女：嗯，有点头疼。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l3', 'lsn16-s2', 3, '男', 115356, 118096, '薬はありますか。', '男：有药吗？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l4', 'lsn16-s2', 4, '女', 118097, 121533, 'あ、あります。今、飲みます。', '女：啊，有。我现在就吃。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l5', 'lsn16-s2', 5, '男', 126490, 131326, 'この土曜日、何をしますか。', '男：这个周六做什么？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l6', 'lsn16-s2', 6, '女', 131717, 138517, 'ええと、今週の土曜日ですね。何もありません。', '女：我想想，这周六啊。没什么安排。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l7', 'lsn16-s2', 7, '男', 140326, 142426, 'じゃ、いっしょに博物館へ行きましょうか。', '男：那一起去博物馆吧？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l8', 'lsn16-s2', 8, '女', 143290, 145920, 'でも、土曜日は雨ですよね。', '女：可是周六下雨吧。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l9', 'lsn16-s2', 9, '男', 147937, 149219, 'えっ？そうですか。じゃ、日曜日は？', '男：诶？是吗。那周日呢？');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l10', 'lsn16-s2', 10, '女', 149534, 150454, '日曜日は会社で残業します。', '女：周日要在公司加班。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l11', 'lsn16-s2', 11, '男', 151360, 153990, 'そうですか。', '男：这样啊。');
INSERT INTO listening_line (id, section_id, line_no, speaker, start_ms, end_ms, text, translation) VALUES ('lsn16-s2-l12', 'lsn16-s2', 12, '女', 154984, 158307, 'やっぱり土曜日に行きましょうか。', '女：还是周六去吧。');
